 if(ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))ImGui::SetTooltip("Include saved receptions in top statistics. Uptime always counts this session's active decoding time. Included automatically when history is used for everything.");
 if(compact&&ImGui::GetItemRectMax().x+ImGui::GetStyle().ItemSpacing.x+ImGui::CalcTextSize("Use saved history for everything").x+35<ImGui::GetWindowPos().x+ImGui::GetWindowContentRegionMax().x)ImGui::SameLine();
 if(ImGui::Checkbox("Use saved history for everything",&historyAll_)){if(historyAll_)historyTableCleared_=historyMapCleared_=0;tableQuery_.offset=0;selected_.reset();changed=true;}
 if(ImGui::IsItemHovered())ImGui::SetTooltip("Load saved receptions into statistics, map and table in the background. Filters still apply. Saved first-heard times replace session times. Off returns to session views. This preference is saved; starts off.");
